        ans[2][16]=1; ans[2][17]=1; ans[2][18]=0; ans[2][19]=0; ans[2][20]=1;
        ans[3][1]=8; ans[3][2]=20; ans[3][3]=0; ans[3][4]=15; ans[3][5]=16;
        ans[3][6]=0; ans[3][7]=0; ans[3][8]=1; ans[3][9]=0; ans[3][10]=0;
        ans[3][11]=0; ans[3][12]=1; ans[3][13]=0; ans[3][14]=0; ans[3][15]=0;
        ans[3][16]=1; ans[3][17]=0; ans[3][18]=0; ans[3][19]=0; ans[3][20]=1;
        // ... (rest of ans initialization omitted for brevity)

        // Initialize ncr array
        for (int a = 0; a < 40; ++a) {
            for (int b = 0; b < 40; ++b) {
                if (b > a) {
                    ncr[a][b] = 0;
                } else if (b == 0 || b == a) {
                    ncr[a][b] = 1;
                } else {
                    ncr[a][b] = ncr[a - 1][b - 1] + ncr[a - 1][b];
                }
            }
        }

        st = new StringTokenizer(br.readLine());
        long R = Long.parseLong(st.nextToken());
        long C = Long.parseLong(st.nextToken());
        String str = br.readLine();

        long n = R + C;
        long[][] blockarea = new long[(int)n][(int)n];
        long[][] totalarea = new long[(int)n + 1][(int)n + 1];

        for (int a = 0; a < n; ++a) {
            for (int b = 0; b < n; ++b) {
                blockarea[a][b] = ncr[a][(int)(R - 1)] * ncr[b][(int)(R - 1)];
            }
        }

        for (int a = 0; a <= n; ++a) {
            for (int b = 0; b <= n; ++b) {
                totalarea[a][b] = 0;
                if (a == 0 || b == 0) continue;
                totalarea[a][b] = totalarea[a][b - 1] + totalarea[a - 1][b] - totalarea[a - 1][b - 1];
                totalarea[a][b] += blockarea[a - 1][b - 1];
            }
        }

        long d = Math.min(2 * n - 1, n + R - 2);

        @SuppressWarnings("unchecked")
        Map<Long, Long>[][] dp = new HashMap[(int)n + 1][(int)n + 1];
        @SuppressWarnings("unchecked")
        Map<Long, Long>[][] bp = new HashMap[(int)n + 1][(int)n + 1];

        for (int i = 0; i <= n; ++i) {
            for (int j = 0; j <= n; ++j) {
                dp[i][j] = new HashMap<>();
                bp[i][j] = new HashMap<>();
            }
        }

        dp[0][0].put(0L, 1L);
        bp[0][0].put(0L, 1L);

        long best = ans[(int)R][(int)C];
        long m1 = (-best + totalarea[(int)n][(int)n]) / 2;
        long m2 = totalarea[(int)n][(int)n] - m1;
        long bestfreq = 0;

        for (int x = 0; x <= n; ++x) {
            for (int y = 0; y < n; ++y) {
                if (x + y + 1 <= d && str.charAt(x + y) != 'B') {
                    Map<Long, Long> currentMap = dp[x][y];
                    Map<Long, Long> nextMap = dp[x][y + 1];
                    for (Map.Entry<Long, Long> entry : currentMap.entrySet()) {
                        long key = entry.getKey();
                        long val = entry.getValue();
                        if (key > m2) continue;
                        nextMap.put(key, nextMap.getOrDefault(key, 0L) + val);
                    }
                }
                if (x + y + 1 <= 2 * n - d && str.charAt((int)(n - x + n - y - 1)) != 'B') {
                    Map<Long, Long> currentMap = bp[x][y];
                    Map<Long, Long> nextMap = bp[x][y + 1];
                    for (Map.Entry<Long, Long> entry : currentMap.entrySet()) {
                        long key = entry.getKey();
                        long val = entry.getValue();
                        if (key > m2) continue;
                        nextMap.put(key, nextMap.getOrDefault(key, 0L) + val);
                    }
                }
            }
            if (x == n) continue;
            for (int y = 0; y <= n; ++y) {
                if (x + y + 1 <= d && str.charAt(x + y) != 'A') {
                    long newarea = totalarea[x + 1][y] - totalarea[x][y];
                    Map<Long, Long> currentMap = dp[x][y];
                    Map<Long, Long> nextMap = dp[x + 1][y];
                    for (Map.Entry<Long, Long> entry : currentMap.entrySet()) {
                        long key = entry.getKey();
                        long val = entry.getValue();
                        if (key + newarea > m2) continue;
                        nextMap.put(key + newarea, nextMap.getOrDefault(key + newarea, 0L) + val);
                    }
                }
                if (x + y + 1 <= 2 * n - d && str.charAt((int)(n - x + n - y - 1)) != 'A') {
                    long newarea2 = totalarea[n - x][n - y] - totalarea[n - x - 1][n - y];
                    Map<Long, Long> currentMap = bp[x][y];
                    Map<Long, Long> nextMap = bp[x + 1][y];
                    for (Map.Entry<Long, Long> entry : currentMap.entrySet()) {
                        long key = entry.getKey();
                        long val = entry.getValue();
                        if (key + newarea2 > m2) continue;
                        nextMap.put(key + newarea2, nextMap.getOrDefault(key + newarea2, 0L) + val);
                    }
                }
                if (x + y + 1 <= d) {
                    dp[x][y].clear();
                }
                if (x + y + 1 <= 2 * n - d) {
                    bp[x][y].clear();
                }
            }
        }

        for (int x = 0; x <= n; ++x) {
            int y = (int)(d - x);
            if (y < 0 || y > n) continue;
            for (Map.Entry<Long, Long> entry : dp[x][y].entrySet()) {
                long c = entry.getKey();
                long freq = entry.getValue();
                bestfreq += freq * bp[n - x][n - y].getOrDefault(m1 - c, 0L);
                if (m1 != m2) {
                    bestfreq += freq * bp[n - x][n - y].getOrDefault(m2 - c, 0L);
                }
            }
        }

        System.out.println(bestfreq);
    }
}
